/// Fetch and reveal a secret value by key from `wasmcloud:secrets`.
fn fetch_secret(key: &str) -> Result<String, String> {
    let secret = store::get(key).map_err(|err| match err {
        store::SecretsError::Upstream(msg) => format!("secret `{key}`: upstream error: {msg}"),
        store::SecretsError::Io(msg) => format!("secret `{key}`: io error: {msg}"),
        store::SecretsError::NotFound => format!("secret `{key}`: not found"),
    })?;
    match reveal::reveal(&secret) {
        store::SecretValue::String(s) => Ok(s),
        store::SecretValue::Bytes(bytes) => {
            String::from_utf8(bytes).map_err(|_| format!("secret `{key}` is not valid UTF-8"))
        }
    }
}

